import json
import logging
from decimal import Decimal, InvalidOperation
from typing import Any
from urllib.parse import urlparse

import requests
from django.conf import settings

from core.url_validation import SSRFBlockedError, safe_get, validate_outbound_url

logger = logging.getLogger(__name__)

_DEFAULT_TIMEOUT_SECONDS = 10
_ZERO_DECIMAL_CURRENCIES = {
    "BIF",
    "CLP",
    "DJF",
    "GNF",
    "ISK",
    "JPY",
    "KMF",
    "KRW",
    "PYG",
    "RWF",
    "UGX",
    "VND",
    "VUV",
    "XAF",
    "XOF",
    "XPF",
}
_CURRENCY_SYMBOLS = {
    "AUD": "$",
    "CAD": "$",
    "EUR": "EUR ",
    "GBP": "GBP ",
    "JPY": "JPY ",
    "USD": "$",
}


class UCPClientError(RuntimeError):
    """Raised when a UCP profile or catalog operation cannot be completed."""


def _normalize_text(value: Any) -> str:
    return str(value or "").strip()


def _listify(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if value is None:
        return []
    return [value]


def _extract_description_text(value: Any) -> str:
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, dict):
        for key in ("plain_text", "text", "markdown", "html"):
            normalized = _normalize_text(value.get(key))
            if normalized:
                return normalized
    return ""


def _minor_units_to_decimal(amount_minor: int, currency: str) -> Decimal:
    fraction_digits = 0 if currency.upper() in _ZERO_DECIMAL_CURRENCIES else 2
    divisor = Decimal(10) ** fraction_digits
    return Decimal(amount_minor) / divisor


def _format_price(amount_minor: Any, currency: Any) -> str | None:
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        return None

    normalized_currency = _normalize_text(currency).upper()
    if not normalized_currency:
        return None

    try:
        amount_decimal = _minor_units_to_decimal(amount_minor, normalized_currency)
    except (InvalidOperation, ValueError):
        return None

    symbol = _CURRENCY_SYMBOLS.get(normalized_currency)
    if normalized_currency in _ZERO_DECIMAL_CURRENCIES:
        number_text = f"{amount_decimal:.0f}"
    else:
        number_text = f"{amount_decimal:.2f}"

    if symbol:
        return f"{symbol}{number_text}"
    return f"{number_text} {normalized_currency}"


def _normalize_price(price: Any) -> dict[str, Any]:
    if not isinstance(price, dict):
        return {
            "amount_minor": None,
            "currency": None,
            "display": None,
        }

    amount_minor = price.get("amount")
    currency = _normalize_text(price.get("currency")).upper() or None
    return {
        "amount_minor": amount_minor if isinstance(amount_minor, int) else None,
        "currency": currency,
        "display": _format_price(amount_minor, currency),
    }


def _normalize_availability_text(value: Any) -> str | None:
    if isinstance(value, str):
        normalized = value.strip()
        return normalized or None
    if isinstance(value, dict):
        for key in ("label", "status", "text", "message"):
            normalized = _normalize_text(value.get(key))
            if normalized:
                return normalized
        for key in ("in_stock", "available"):
            if isinstance(value.get(key), bool):
                return "In stock" if value[key] else "Out of stock"
    return None


def _normalize_category_labels(value: Any) -> list[str]:
    labels: list[str] = []
    for category in _listify(value):
        if isinstance(category, str):
            normalized = category.strip()
            if normalized:
                labels.append(normalized)
            continue
        if not isinstance(category, dict):
            continue
        normalized = _normalize_text(category.get("label") or category.get("value"))
        if normalized:
            labels.append(normalized)
    return labels


def _normalize_media_entry(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    media_url = _normalize_text(value.get("url"))
    if not media_url:
        return None
    return {
        "url": media_url,
        "alt_text": _normalize_text(value.get("alt_text")) or None,
        "type": _normalize_text(value.get("type")) or None,
    }


class UCPCatalogClient:
    def __init__(self, *, session: requests.Session | None = None) -> None:
        self.session = session or requests.Session()
        self.platform_profile_url = _normalize_text(
            getattr(settings, "FAMILY_AGENT_UCP_PLATFORM_PROFILE_URL", "")
        )

    def search_catalog(
        self,
        *,
        merchant_url: str | None = None,
        merchant_domain: str | None = None,
        query: str | None = None,
        categories: list[str] | None = None,
        min_price_minor: int | None = None,
        max_price_minor: int | None = None,
        currency: str | None = None,
        intent: str | None = None,
        limit: int = 5,
        cursor: str | None = None,
    ) -> dict[str, Any]:
        profile_url, normalized_domain = self._build_profile_url(
            merchant_url=merchant_url,
            merchant_domain=merchant_domain,
        )
        profile = self._fetch_profile(profile_url)
        service_endpoint = self._resolve_rest_service_endpoint(profile)
        if not service_endpoint:
            raise UCPClientError(
                "This merchant does not advertise a UCP shopping REST endpoint."
            )
        if not self._supports_capability(
            profile, capability_name="dev.ucp.shopping.catalog.search"
        ):
            raise UCPClientError(
                "This merchant does not advertise UCP catalog search support."
            )

        validated_endpoint = validate_outbound_url(service_endpoint)
        if validated_endpoint is None:
            raise UCPClientError("Blocked unsafe merchant UCP endpoint.")

        request_payload = self._build_search_payload(
            query=query,
            categories=categories,
            min_price_minor=min_price_minor,
            max_price_minor=max_price_minor,
            currency=currency,
            intent=intent,
            limit=limit,
            cursor=cursor,
        )
        response = self.session.post(
            f"{validated_endpoint.rstrip('/')}/catalog/search",
            json=request_payload,
            timeout=_DEFAULT_TIMEOUT_SECONDS,
            headers=self._build_headers(),
            allow_redirects=False,
        )
        response_payload = self._load_json(response)

        if response.status_code >= 400:
            raise UCPClientError(
                _normalize_text(
                    response_payload.get("content")
                    or response_payload.get("message")
                    or response_payload.get("error")
                )
                or f"Merchant returned HTTP {response.status_code}."
            )

        products = [
            self._normalize_product(product, fallback_domain=normalized_domain)
            for product in _listify(response_payload.get("products"))
            if isinstance(product, dict)
        ]

        return {
            "ok": True,
            "merchant_domain": normalized_domain,
            "profile_url": profile_url,
            "service_endpoint": validated_endpoint,
            "products": products,
            "pagination": (
                response_payload.get("pagination")
                if isinstance(response_payload.get("pagination"), dict)
                else {}
            ),
            "messages": (
                response_payload.get("messages")
                if isinstance(response_payload.get("messages"), list)
                else []
            ),
        }

    def _build_profile_url(
        self,
        *,
        merchant_url: str | None,
        merchant_domain: str | None,
    ) -> tuple[str, str]:
        normalized_merchant_url = _normalize_text(merchant_url)
        normalized_domain = _normalize_text(merchant_domain)

        if normalized_merchant_url:
            parsed = urlparse(
                normalized_merchant_url
                if "://" in normalized_merchant_url
                else f"https://{normalized_merchant_url}"
            )
            hostname = _normalize_text(parsed.hostname)
            if not hostname:
                raise UCPClientError("merchant_url must include a valid hostname.")
            scheme = parsed.scheme if parsed.scheme in {"http", "https"} else "https"
            return f"{scheme}://{hostname}/.well-known/ucp", hostname

        if normalized_domain:
            parsed = urlparse(
                normalized_domain
                if "://" in normalized_domain
                else f"https://{normalized_domain}"
            )
            hostname = _normalize_text(parsed.hostname)
            if not hostname:
                raise UCPClientError("merchant_domain must be a valid hostname.")
            return f"https://{hostname}/.well-known/ucp", hostname

        raise UCPClientError(
            "Provide a merchant_url or merchant_domain to search a UCP catalog."
        )

    def _fetch_profile(self, profile_url: str) -> dict[str, Any]:
        try:
            response = safe_get(
                profile_url,
                timeout=_DEFAULT_TIMEOUT_SECONDS,
                headers=self._build_headers(),
            )
        except (SSRFBlockedError, requests.RequestException) as exc:
            raise UCPClientError(
                f"Unable to fetch the merchant UCP profile: {exc}"
            ) from exc

        if response.status_code >= 400:
            raise UCPClientError(
                f"Merchant UCP profile returned HTTP {response.status_code}."
            )

        payload = self._load_json(response)
        ucp_payload = payload.get("ucp")
        if not isinstance(ucp_payload, dict):
            raise UCPClientError("Merchant UCP profile returned invalid JSON.")
        return ucp_payload

    def _resolve_rest_service_endpoint(self, profile: dict[str, Any]) -> str | None:
        services = profile.get("services")
        if not isinstance(services, dict):
            return None

        for service in _listify(services.get("dev.ucp.shopping")):
            if not isinstance(service, dict):
                continue

            rest_transport = service.get("rest")
            if isinstance(rest_transport, dict):
                endpoint = _normalize_text(rest_transport.get("endpoint"))
                if endpoint:
                    return endpoint

            if _normalize_text(service.get("transport")).lower() == "rest":
                endpoint = _normalize_text(service.get("endpoint"))
                if endpoint:
                    return endpoint

        return None

    def _supports_capability(
        self, profile: dict[str, Any], *, capability_name: str
    ) -> bool:
        capabilities = profile.get("capabilities")
        if not isinstance(capabilities, dict):
            return True
        return bool(_listify(capabilities.get(capability_name)))

    def _build_headers(self) -> dict[str, str]:
        headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "User-Agent": "ClanCal-FamilyPlanner/1.0",
        }
        if self.platform_profile_url:
            headers["UCP-Agent"] = f'profile="{self.platform_profile_url}"'
        return headers

    def _build_search_payload(
        self,
        *,
        query: str | None,
        categories: list[str] | None,
        min_price_minor: int | None,
        max_price_minor: int | None,
        currency: str | None,
        intent: str | None,
        limit: int,
        cursor: str | None,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {}
        normalized_query = _normalize_text(query)
        if normalized_query:
            payload["query"] = normalized_query

        normalized_currency = _normalize_text(currency).upper()
        normalized_intent = _normalize_text(intent)
        if normalized_currency or normalized_intent:
            payload["context"] = {
                key: value
                for key, value in {
                    "currency": normalized_currency or None,
                    "intent": normalized_intent or None,
                }.items()
                if value
            }

        filters: dict[str, Any] = {}
        if categories:
            normalized_categories = [
                _normalize_text(category)
                for category in categories
                if _normalize_text(category)
            ]
            if normalized_categories:
                filters["categories"] = normalized_categories
        price_filter = {
            key: value
            for key, value in {
                "min": min_price_minor if isinstance(min_price_minor, int) else None,
                "max": max_price_minor if isinstance(max_price_minor, int) else None,
            }.items()
            if value is not None
        }
        if price_filter:
            filters["price"] = price_filter
        if filters:
            payload["filters"] = filters

        normalized_pagination = {
            key: value
            for key, value in {
                "limit": max(1, min(int(limit or 5), 10)),
                "cursor": _normalize_text(cursor) or None,
            }.items()
            if value is not None
        }
        if normalized_pagination:
            payload["pagination"] = normalized_pagination

        if not payload.get("query") and not payload.get("filters") and not cursor:
            raise UCPClientError(
                "UCP catalog search requires a query, filters, or a pagination cursor."
            )
        return payload

    def _load_json(self, response: requests.Response) -> dict[str, Any]:
        try:
            payload = response.json()
        except json.JSONDecodeError as exc:
            logger.warning("UCP response did not contain valid JSON: %s", exc)
            raise UCPClientError("Merchant returned invalid JSON.") from exc

        if not isinstance(payload, dict):
            raise UCPClientError("Merchant returned an unexpected JSON payload.")
        return payload

    def _normalize_product(
        self, product: dict[str, Any], *, fallback_domain: str
    ) -> dict[str, Any]:
        product_media = (
            _normalize_media_entry(_listify(product.get("media"))[:1][0])
            if _listify(product.get("media"))
            else None
        )
        variants = [
            variant
            for variant in _listify(product.get("variants"))
            if isinstance(variant, dict)
        ]
        featured_variant = variants[0] if variants else {}
        variant_media = (
            _normalize_media_entry(_listify(featured_variant.get("media"))[:1][0])
            if _listify(featured_variant.get("media"))
            else None
        )
        featured_media = variant_media or product_media
        price = _normalize_price(featured_variant.get("price"))
        list_price = _normalize_price(featured_variant.get("list_price"))
        seller = (
            featured_variant.get("seller")
            if isinstance(featured_variant.get("seller"), dict)
            else {}
        )
        merchant_name = _normalize_text(seller.get("name")) or fallback_domain

        return {
            "id": _normalize_text(product.get("id")),
            "title": _normalize_text(product.get("title")),
            "url": _normalize_text(featured_variant.get("url") or product.get("url")),
            "description": _extract_description_text(
                featured_variant.get("description") or product.get("description")
            ),
            "merchant_name": merchant_name,
            "merchant_domain": fallback_domain,
            "image_url": featured_media["url"] if featured_media else None,
            "image_alt": featured_media["alt_text"] if featured_media else None,
            "variant_id": _normalize_text(featured_variant.get("id")),
            "variant_title": _normalize_text(featured_variant.get("title")),
            "price_text": price["display"],
            "list_price_text": list_price["display"],
            "availability_text": _normalize_availability_text(
                featured_variant.get("availability")
            ),
            "category_labels": _normalize_category_labels(product.get("categories")),
        }
