from __future__ import annotations

import logging
from typing import Any
from urllib.parse import urlparse

from django.contrib.auth.models import User
from django.db import IntegrityError, transaction

from calendars.models import CalendarVisibility, ExternalCalendarAccount
from calendars.utils.ics_metadata import (
    fetch_ics_metadata,
    normalize_and_validate_ics_url,
)

logger = logging.getLogger(__name__)

ICS_PROVIDER = "ICS"
_DEFAULT_ACCOUNT_NAME = "Imported calendar"


class CalendarUrlSubscriptionError(ValueError):
    """Raised when a calendar URL cannot be normalized into a safe subscription."""


def _build_source_host(ical_url: str) -> str:
    return (urlparse(ical_url).hostname or "").strip().lower()


def _truncate_string(value: str, *, max_length: int) -> str:
    normalized = value.strip()
    if not normalized:
        return ""
    return normalized[:max_length].strip()


def _serialize_preview_metadata(metadata: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(metadata, dict):
        return {}

    serialized: dict[str, Any] = {}
    for key in (
        "calendar_name",
        "calendar_description",
        "event_count",
        "timezone",
        "suggested_names",
    ):
        value = metadata.get(key)
        if value is None:
            continue
        if isinstance(value, str) and not value.strip():
            continue
        if isinstance(value, list) and not value:
            continue
        serialized[key] = value
    return serialized


def _resolve_account_name(
    *,
    requested_name: str | None,
    metadata: dict[str, Any] | None,
