    def _normalize_text(self, value: Any) -> str:
        return str(value or "").strip()

    def _normalize_group_plan_template(self, value: Any) -> str:
        normalized_value = re.sub(
            r"[^A-Z0-9]+",
            "_",
            self._normalize_text(value).upper(),
        ).strip("_")
