            "owner_username": calendar.user.username,
            "sync_enabled": calendar.sync_enabled,
            "is_active": calendar.is_active,
        }

    def _serialize_task_summary(self, task: FamilyTask) -> dict[str, Any]:
        return {
            "id": str(task.id),
            "title": task.title,
            "notes": task.notes,
            "status": task.status,
            "due_at": task.due_at.isoformat() if task.due_at else None,
            "assigned_to": self._serialize_user_summary(task.assigned_to),
            "linked_event": self._serialize_event_summary(task.linked_event),
            "task_kind": task.task_kind,
