    def _apply_task_bucket_filter(
        self, queryset: models.QuerySet[FamilyTask], *, bucket: str | None
    ) -> models.QuerySet[FamilyTask]:
        normalized_bucket = self._normalize_text(bucket).lower()
        now = timezone.now()
        if normalized_bucket == "today":
            return queryset.filter(
                due_at__isnull=False,
                due_at__date=timezone.localdate(now),
            )
        if normalized_bucket == "overdue":
            return queryset.filter(due_at__lt=now)
        if normalized_bucket == "this_week":
            return queryset.filter(
                due_at__isnull=False,
                due_at__gte=now,
                due_at__lte=now + timedelta(days=7),
            )
        return queryset

    def _apply_task_assignee_filter(
        self,
        queryset: models.QuerySet[FamilyTask],
        *,
        assignee: str | None,
        user: User,
    ) -> models.QuerySet[FamilyTask]:
        normalized_assignee = self._normalize_text(assignee).lower()
        if not normalized_assignee or normalized_assignee == "all":
            return queryset
        if normalized_assignee == "me":
            return queryset.filter(assigned_to=user)
        if normalized_assignee == "unassigned":
            return queryset.filter(assigned_to__isnull=True)
        try:
            return queryset.filter(assigned_to_id=int(normalized_assignee))
        except (TypeError, ValueError):
            return queryset.none()

    def _parse_group_plan_option_datetime(
        self, value: Any, *, field_name: str
    ) -> datetime | None:
        normalized = self._normalize_text(value)
        if not normalized:
            return None

        parsed = parse_datetime(normalized)
        if parsed is None:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=NETWORK_PLAN_TIMEZONE)
        return parsed.astimezone(datetime_timezone.utc)

    def _normalize_group_plan_option(self, option: Any) -> Any:
        if not isinstance(option, dict):
            return option

        normalized_option = dict(option)
        start_time = self._parse_group_plan_option_datetime(
            option.get("start_time"),
            field_name="start_time",
        )
        end_time = self._parse_group_plan_option_datetime(
            option.get("end_time"),
            field_name="end_time",
        )
        if start_time is not None:
            normalized_option["start_time"] = self._format_utc_iso(start_time)
        if end_time is not None:
            normalized_option["end_time"] = self._format_utc_iso(end_time)
        return normalized_option

    def _parse_plan_option_start(self, option: dict[str, Any]) -> datetime | None:
        start_time = self._parse_group_plan_option_datetime(
            option.get("start_time"),
            field_name="start_time",
        )
        if start_time is None:
            return None
        return start_time.astimezone(NETWORK_PLAN_TIMEZONE)

    def _format_plan_option_preview(self, option: dict[str, Any]) -> str | None:
        start_time = self._parse_plan_option_start(option)
        if start_time is None:
            return (
                self._normalize_text(option.get("label"))
                or self._normalize_text(option.get("title"))
                or None
            )

        date_label = (
            f"{start_time.strftime('%A')}, {start_time.strftime('%b')} {start_time.day}"
        )
        time_label = start_time.strftime("%I:%M %p").lstrip("0")
        return f"{date_label} at {time_label}"

    def _build_verified_group_plan_preview_text(
        self,
        *,
        title: str,
        plan_options: list[dict[str, Any]],
        fallback_text: str,
    ) -> str:
        preview_items = [
            preview
            for option in plan_options[:3]
            if isinstance(option, dict)
            for preview in [self._format_plan_option_preview(option)]
            if preview
        ]
        if not preview_items:
            return fallback_text or "Verified options ready for review."

        title_prefix = f" for {title}" if title else ""
        preview_text = f"Verified options{title_prefix}: " + "; ".join(preview_items)
        remaining_count = max(len(plan_options) - len(preview_items), 0)
        if remaining_count:
            preview_text += f"; plus {remaining_count} more"
        return preview_text + "."

    def _build_verified_group_plan_assistant_text(
        self, proposal: dict[str, Any]
    ) -> str | None:
        payload = proposal.get("payload_json")
        if not isinstance(payload, dict):
            return None

        raw_plan_options = payload.get("plan_options")
        if not isinstance(raw_plan_options, list) or not raw_plan_options:
            return None

        title = self._normalize_text(payload.get("title")) or self._normalize_text(
            proposal.get("summary")
        )
        preview_text = self._build_verified_group_plan_preview_text(
            title=title,
            plan_options=[
                option for option in raw_plan_options if isinstance(option, dict)
            ],
            fallback_text=self._normalize_text(proposal.get("preview_text")),
        )
        return (
            f"{preview_text} Review the plan below if you want to turn it into a poll."
        )

    def sanitize_family_network_assistant_text(
        self,
        assistant_text: Any,
        *,
        proposals: list[Any],
        context_payload: dict[str, Any],
    ) -> str:
        normalized_text = self._normalize_text(assistant_text)
        if not normalized_text:
            return normalized_text

        is_family_network_context = self._normalize_text(
            context_payload.get("source_screen")
        ) == "family_network" and bool(
            self._normalize_text(context_payload.get("group_id"))
        )
        if not is_family_network_context:
            return normalized_text

        if not re.search(
            r"could\s+not\s+verify|couldn't\s+verify|not\s+confirmed|unable\s+to\s+verify|within\s+the\s+official\s+run\s+window",
            normalized_text,
            re.IGNORECASE,
        ):
            return normalized_text

        for proposal in proposals:
            if not isinstance(proposal, dict):
                continue
            if not self._is_group_plan_proposal_type(proposal.get("proposal_type")):
                continue

            rewritten_text = self._build_verified_group_plan_assistant_text(proposal)
            if rewritten_text:
                return rewritten_text

        return normalized_text

    def _parse_group_plan_duration_minutes(self, payload: dict[str, Any]) -> int:
        note_text = " ".join(
            self._normalize_text(note)
            for note in payload.get("notes", [])
            if self._normalize_text(note)
        )
        if not note_text:
            return DEFAULT_GROUP_PLAN_DURATION_MINUTES

        hours_match = re.search(r"(\d+)\s*hours?", note_text, re.IGNORECASE)
        minutes_match = re.search(r"(\d+)\s*minutes?", note_text, re.IGNORECASE)
        if not hours_match and not minutes_match:
            return DEFAULT_GROUP_PLAN_DURATION_MINUTES

        hours = int(hours_match.group(1)) if hours_match else 0
        minutes = int(minutes_match.group(1)) if minutes_match else 0
        return max(hours * 60 + minutes, 30)

    def _build_group_plan_location(self, payload: dict[str, Any]) -> str:
        venue = self._normalize_text(payload.get("venue"))
        venue_address = self._normalize_text(payload.get("venue_address"))
        if venue and venue_address:
            return f"{venue}, {venue_address}"
        return venue or venue_address

    def _parse_showtime_start(self, date_text: str, time_text: str) -> datetime | None:
        normalized_date = self._normalize_text(date_text)
        normalized_time = self._normalize_text(time_text).upper().replace(".", "")
        if not normalized_date or not normalized_time:
            return None

        candidate = " ".join([normalized_date, normalized_time])
        for fmt in ("%Y-%m-%d %I:%M %p", "%Y-%m-%d %I %p"):
            try:
                start = datetime.strptime(candidate, fmt)
                return start.replace(tzinfo=NETWORK_PLAN_TIMEZONE)
            except ValueError:
                continue
        return None

    def _convert_showtime_option_to_plan_option(
        self,
        option: dict[str, Any],
        *,
        option_kind: str,
        option_index: int,
        duration_minutes: int,
        location: str,
    ) -> tuple[dict[str, Any] | None, str | None]:
        day = self._normalize_text(option.get("day"))
        date_text = self._normalize_text(option.get("date"))
        time_text = self._normalize_text(option.get("time"))
        note_text = self._normalize_text(option.get("note"))
        start_time = self._parse_showtime_start(date_text, time_text)
        if start_time is None:
            skipped_reason = " ".join(
                value
                for value in [
                    day or None,
                    date_text or None,
                    note_text or ("time not confirmed" if not time_text else None),
                ]
                if value
            )
            return None, skipped_reason or None

        end_time = start_time + timedelta(minutes=duration_minutes)
        priority = option.get("priority")
        if option_kind == "fallback":
            suffix = "fallback"
        elif priority == 1:
            suffix = "first choice"
        elif priority == 2:
            suffix = "second choice"
        elif priority == 3:
            suffix = "third choice"
        else:
            suffix = f"option {option_index + 1}"

        return (
            {
                "label": " ".join(value for value in [day or None, suffix] if value),
                "title": f"{time_text} performance" if time_text else day,
                "description": note_text,
                "location": location,
                "start_time": self._format_utc_iso(start_time),
                "end_time": self._format_utc_iso(end_time),
            },
            None,
        )

    def normalize_family_network_group_plan_payload(
        self,
        payload: Any,
        *,
        context_group_id: str | None,
        summary: str,
        preview_text: str,
    ) -> dict[str, Any]:
        normalized_payload = dict(payload) if isinstance(payload, dict) else {}
        group_id = self._normalize_text(
            normalized_payload.get("group_id") or context_group_id
        )
        raw_plan_options = normalized_payload.get("plan_options")
        if isinstance(raw_plan_options, list):
            normalized_payload["plan_options"] = [
                self._normalize_group_plan_option(option) for option in raw_plan_options
            ]
            normalized_payload["group_id"] = group_id
            normalized_payload["title"] = (
                self._normalize_text(normalized_payload.get("title")) or summary
            )
            normalized_payload["template"] = self._normalize_group_plan_template(
                normalized_payload.get("template")
            )
            normalized_payload["mode"] = self._normalize_group_plan_mode(
                normalized_payload.get("mode")
            )
            normalized_payload["description"] = self._normalize_text(
                normalized_payload.get("description")
            )
            return normalized_payload

        preferred_options = normalized_payload.get("preferred_options")
        fallback_options = normalized_payload.get("fallback_options")
        showtime_options: list[tuple[str, Any]] = []
        if isinstance(preferred_options, list):
            showtime_options.extend(
                ("preferred", option) for option in preferred_options
            )
        if isinstance(fallback_options, list):
            showtime_options.extend(("fallback", option) for option in fallback_options)

        if not showtime_options:
            normalized_payload["group_id"] = group_id
            return normalized_payload

        duration_minutes = self._parse_group_plan_duration_minutes(normalized_payload)
        location = self._build_group_plan_location(normalized_payload)
        converted_options: list[dict[str, Any]] = []

        for option_index, (option_kind, option) in enumerate(showtime_options):
            if not isinstance(option, dict):
                continue
            converted_option, skipped_option = (
                self._convert_showtime_option_to_plan_option(
                    option,
                    option_kind=option_kind,
                    option_index=option_index,
                    duration_minutes=duration_minutes,
                    location=location,
                )
            )
            if converted_option is not None:
                converted_options.append(converted_option)
            elif skipped_option:
                continue

        description_parts = [
            self._normalize_text(normalized_payload.get("description")),
            *[
                self._normalize_text(note)
                for note in normalized_payload.get("notes", [])
                if self._normalize_text(note)
            ],
        ]

        description = " ".join(
            part if part.endswith(".") else f"{part}."
            for part in description_parts
            if part
        )

        return {
            "group_id": group_id,
            "title": self._normalize_text(normalized_payload.get("title")) or summary,
            "description": description,
            "template": "OTHER",
            "mode": "TIME_ONLY",
            "plan_options": converted_options,
            "source_preview_text": preview_text,
        }

    def normalize_family_network_group_plan_proposal(
        self,
        proposal: dict[str, Any],
        *,
        context_group_id: str | None,
        family: FamilyGroup | None = None,
    ) -> dict[str, Any]:
        normalized_proposal = dict(proposal)
        if not self._is_group_plan_proposal_type(
            self._normalize_text(normalized_proposal.get("proposal_type"))
        ):
            return normalized_proposal

        original_proposal_type = self._normalize_text(
            normalized_proposal.get("proposal_type")
        )
        normalized_proposal["proposal_type"] = FamilyAgentProposal.Type.GROUP_PLAN
        normalized_proposal["payload_json"] = (
            self.normalize_family_network_group_plan_payload(
                normalized_proposal.get("payload_json"),
                context_group_id=context_group_id,
                summary=self._normalize_text(normalized_proposal.get("summary")),
                preview_text=self._normalize_text(
                    normalized_proposal.get("preview_text")
                ),
            )
        )
        payload = normalized_proposal.get("payload_json")
        if isinstance(payload, dict) and family is not None:
            coordination_review = self._build_group_plan_coordination_review(
                family=family,
                context_group_id=context_group_id,
                payload=payload,
            )
            if coordination_review:
                payload = dict(payload)
                payload["coordination_review"] = coordination_review
                normalized_proposal["payload_json"] = payload

        if isinstance(payload, dict) and (
            original_proposal_type != FamilyAgentProposal.Type.GROUP_PLAN
            or "source_preview_text" in payload
        ):
            raw_plan_options = payload.get("plan_options")
            normalized_proposal["preview_text"] = (
                self._build_verified_group_plan_preview_text(
                    title=self._normalize_text(payload.get("title"))
                    or self._normalize_text(normalized_proposal.get("summary")),
                    plan_options=[
                        option
                        for option in raw_plan_options
                        if isinstance(option, dict)
                    ]
                    if isinstance(raw_plan_options, list)
                    else [],
                    fallback_text=self._normalize_text(
                        payload.get("source_preview_text")
                        or normalized_proposal.get("preview_text")
                    ),
                )
            )
        return normalized_proposal

    def _is_agent_enabled_for_family(self, family: FamilyGroup) -> bool:
        try:
            feature_settings = family.feature_settings
        except FamilyFeatureSettings.DoesNotExist:
            return False
        return bool(feature_settings.agent_enabled)

    def _parse_coordination_candidate_times(
        self, option: dict[str, Any]
    ) -> tuple[datetime | None, datetime | None]:
        start_time = self._parse_group_plan_option_datetime(
            option.get("start_time"),
            field_name="start_time",
        )
        end_time = self._parse_group_plan_option_datetime(
            option.get("end_time"),
            field_name="end_time",
        )
        if start_time is None or end_time is None:
            return None, None
        return start_time, end_time

    def _build_coordination_slot_label(
        self, option: dict[str, Any], option_index: int
    ) -> str:
        return (
            self._normalize_text(option.get("label"))
            or self._normalize_text(option.get("title"))
            or f"Option {option_index + 1}"
        )

    def _build_coarse_coordination_window(
        self, *, start_time: datetime, end_time: datetime
    ) -> str:
        local_start = start_time.astimezone(NETWORK_PLAN_TIMEZONE)
        local_end = end_time.astimezone(NETWORK_PLAN_TIMEZONE)
        if local_start.hour < 12:
            daypart = "morning"
        elif local_start.hour < 17:
            daypart = "afternoon"
        else:
            daypart = "evening"
        if local_start.date() == local_end.date():
            return f"{local_start.strftime('%A')} {daypart}"
        return f"{local_start.strftime('%A')} {daypart} to {local_end.strftime('%A')} {daypart}"

    def _has_family_conflict(
        self,
        *,
        family: FamilyGroup,
        start_time: datetime,
        end_time: datetime,
    ) -> bool:
        return Event.objects.filter(
            family_group=family,
            start_time__lt=end_time,
            end_time__gt=start_time,
        ).exists()

    def _build_group_plan_coordination_review(
        self,
        *,
        family: FamilyGroup,
        context_group_id: str | None,
        payload: dict[str, Any],
    ) -> dict[str, Any] | None:
        group_id = self._normalize_text(payload.get("group_id") or context_group_id)
        if not group_id:
            return None

        target_group = (
            FamilyGroup.objects.select_related("feature_settings")
            .filter(id=group_id)
            .first()
        )
        if target_group is None or self._get_group_kind(target_group) != "META":
            return None

        network_family_ids = list(
            MetaFamilyMembership.objects.filter(meta_family=target_group).values_list(
                "family_id", flat=True
            )
        )
        if not network_family_ids:
            return None

        connected_families = {
            str(group.id): group
            for group in FamilyGroup.objects.select_related("feature_settings")
            .filter(id__in=network_family_ids)
            .order_by("name")
        }
        current_family_id = str(family.id)
        connected_families[current_family_id] = family
        ordered_families = [
            connected_families[current_family_id],
            *[
                group
                for family_id, group in connected_families.items()
                if family_id != current_family_id
            ],
        ]

        raw_plan_options = payload.get("plan_options")
        candidate_slots: list[dict[str, Any]] = []
        if isinstance(raw_plan_options, list):
            for option_index, option in enumerate(raw_plan_options):
                if not isinstance(option, dict):
                    continue
                start_time, end_time = self._parse_coordination_candidate_times(option)
                if start_time is None or end_time is None or start_time >= end_time:
                    continue
                candidate_slots.append(
                    {
                        "slot_id": self._normalize_text(option.get("id"))
                        or f"slot-{option_index + 1}",
                        "label": self._build_coordination_slot_label(
                            option, option_index
                        ),
                        "start_time": self._format_utc_iso(start_time),
                        "end_time": self._format_utc_iso(end_time),
                        "_start_time": start_time,
                        "_end_time": end_time,
                    }
                )
                if (
                    len(candidate_slots)
                    >= DEFAULT_GROUP_PLAN_COORDINATION_MAX_CANDIDATE_SLOTS_PER_ROUND
                ):
                    break

        if not candidate_slots:
            return None

        family_evaluations: dict[str, dict[str, Any]] = {}
        for target_family in ordered_families:
            target_family_id = str(target_family.id)
            if (
                target_family_id != current_family_id
                and not self._is_agent_enabled_for_family(target_family)
            ):
                family_evaluations[target_family_id] = {
                    "family_name": target_family.name,
                    "family_id": target_family_id,
                    "kind": "manual_followup_required",
                    "statuses": {},
                    "alternative_windows": [],
                }
                continue

            try:
                slot_statuses: dict[str, str] = {}
                alternative_windows: list[str] = []
                for candidate in candidate_slots:
                    is_blocked = self._has_family_conflict(
                        family=target_family,
                        start_time=candidate["_start_time"],
                        end_time=candidate["_end_time"],
                    )
                    slot_statuses[candidate["slot_id"]] = "no" if is_blocked else "yes"
                    if not is_blocked:
                        coarse_window = self._build_coarse_coordination_window(
                            start_time=candidate["_start_time"],
                            end_time=candidate["_end_time"],
                        )
                        if coarse_window not in alternative_windows:
                            alternative_windows.append(coarse_window)
                family_evaluations[target_family_id] = {
                    "family_name": target_family.name,
                    "family_id": target_family_id,
                    "kind": "coordinated",
                    "statuses": slot_statuses,
                    "alternative_windows": alternative_windows[
                        :DEFAULT_GROUP_PLAN_COORDINATION_MAX_ALTERNATIVE_WINDOWS_PER_REPLY
                    ],
                }
            except Exception:
                family_evaluations[target_family_id] = {
                    "family_name": target_family.name,
                    "family_id": target_family_id,
                    "kind": "error",
                    "statuses": {},
                    "alternative_windows": [],
                }

        round_candidates: list[dict[str, Any]] = []
        for candidate in candidate_slots:
            aggregates = {
                "yes": 0,
                "no": 0,
                "maybe": 0,
                "manual_followup_required": 0,
                "agent_unavailable": 0,
                "error": 0,
            }
            family_responses: list[dict[str, Any]] = []
            for target_family in ordered_families:
                target_family_id = str(target_family.id)
                evaluation = family_evaluations[target_family_id]
                reason_code = "available"
                alternative_windows = []
                if evaluation["kind"] == "manual_followup_required":
                    status = "manual_followup_required"
                    reason_code = "manual_confirmation_needed"
                elif evaluation["kind"] == "error":
                    status = "error"
                    reason_code = "coordination_error"
                else:
                    status = evaluation["statuses"].get(candidate["slot_id"], "maybe")
                    if status == "no":
                        reason_code = "busy"
                        alternative_windows = evaluation["alternative_windows"]
                    elif status == "maybe":
                        reason_code = "needs_human_confirm"

                aggregates[status] = aggregates.get(status, 0) + 1
                family_responses.append(
                    {
                        "family_id": target_family_id,
                        "family_name": evaluation["family_name"],
                        "status": status,
                        "reason_code": reason_code,
                        "is_current_family": target_family_id == current_family_id,
                        "alternative_windows": alternative_windows,
                    }
                )

            round_candidates.append(
                {
                    "slot_id": candidate["slot_id"],
                    "label": candidate["label"],
                    "start_time": candidate["start_time"],
                    "end_time": candidate["end_time"],
                    "family_responses": family_responses,
                    "aggregates": aggregates,
                }
            )

        ranked_candidates = sorted(
            round_candidates,
            key=lambda candidate: (
                candidate["aggregates"]["no"],
                candidate["aggregates"]["error"],
                candidate["aggregates"]["manual_followup_required"],
                -candidate["aggregates"]["yes"],
            ),
        )
        best_candidates = ranked_candidates[:2]
        if best_candidates and best_candidates[0]["aggregates"]["no"] == 0:
            stop_reason = "consensus_found"
        elif all(candidate["aggregates"]["yes"] == 0 for candidate in round_candidates):
            stop_reason = "all_declined"
        else:
            stop_reason = "no_new_information"

        if not best_candidates:
            confidence = "low"
        elif (
            best_candidates[0]["aggregates"]["no"] == 0
            and best_candidates[0]["aggregates"]["manual_followup_required"] == 0
        ):
            confidence = "high"
        elif best_candidates[0]["aggregates"]["no"] == 0:
            confidence = "medium"
        else:
            confidence = "low"

        for candidate in candidate_slots:
            candidate.pop("_start_time", None)
            candidate.pop("_end_time", None)

        return {
            "search_id": str(uuid4()),
            "search_status": "completed",
            "tentative_flow": True,
            "executed_rounds": 1,
            "stop_reason": stop_reason,
            "confidence": confidence,
            "config": {
                "max_rounds": DEFAULT_GROUP_PLAN_COORDINATION_MAX_ROUNDS,
                "max_candidate_slots_per_round": DEFAULT_GROUP_PLAN_COORDINATION_MAX_CANDIDATE_SLOTS_PER_ROUND,
                "max_alternative_windows_per_reply": DEFAULT_GROUP_PLAN_COORDINATION_MAX_ALTERNATIVE_WINDOWS_PER_REPLY,
                "dedupe_window_minutes": DEFAULT_GROUP_PLAN_COORDINATION_DEDUPE_WINDOW_MINUTES,
            },
            "summary": {
                "coordinator_family_id": current_family_id,
                "coordinated_families": [
                    {
                        "family_id": evaluation["family_id"],
                        "family_name": evaluation["family_name"],
                    }
                    for evaluation in family_evaluations.values()
                    if evaluation["kind"] == "coordinated"
                ],
                "manual_followup_families": [
                    {
                        "family_id": evaluation["family_id"],
                        "family_name": evaluation["family_name"],
                    }
                    for evaluation in family_evaluations.values()
                    if evaluation["kind"] == "manual_followup_required"
                ],
                "agent_error_families": [
                    {
                        "family_id": evaluation["family_id"],
                        "family_name": evaluation["family_name"],
                    }
                    for evaluation in family_evaluations.values()
                    if evaluation["kind"] == "error"
                ],
                "best_candidates": [
                    {
                        "slot_id": candidate["slot_id"],
                        "label": candidate["label"],
                        "start_time": candidate["start_time"],
                        "end_time": candidate["end_time"],
                        "yes_count": candidate["aggregates"]["yes"],
                        "no_count": candidate["aggregates"]["no"],
                        "maybe_count": candidate["aggregates"]["maybe"],
                        "manual_followup_count": candidate["aggregates"][
                            "manual_followup_required"
                        ],
                    }
                    for candidate in best_candidates
                ],
            },
            "rounds": [
                {
                    "round_number": 1,
                    "candidate_slots": round_candidates,
                }
            ],
            "note": GROUP_PLAN_COORDINATION_PRIVACY_NOTE,
        }

    def _get_proposal_context_group_id(
        self, proposal: FamilyAgentProposal
    ) -> str | None:
        trigger_message = getattr(
            getattr(proposal, "run", None), "trigger_message", None
        )
        context_json = getattr(trigger_message, "context_json", None)
        if not isinstance(context_json, dict):
            return None
        group_id = self._normalize_text(context_json.get("group_id"))
        return group_id or None

    def _get_group_kind(self, family: FamilyGroup) -> str:
        try:
            return FamilyGroupType.objects.get(family=family).type
        except FamilyGroupType.DoesNotExist:
            return "IMMEDIATE"

    def _get_accessible_group(self, user: User, group_id: str) -> FamilyGroup | None:
        group = FamilyGroup.objects.filter(id=group_id).first()
        if group is None:
            return None

        if FamilyMembership.objects.filter(
            user=user,
            family=group,
            is_active=True,
        ).exists():
            return group

        if self._get_group_kind(group) != "META":
            return None

        if MetaFamilyMembership.objects.filter(
            meta_family=group,
            family__memberships__user=user,
            family__memberships__is_active=True,
        ).exists():
            return group

        return None

    def _read_active_group_summary(self, group: FamilyGroup) -> dict[str, Any]:
        group_kind = self._get_group_kind(group)
        summary: dict[str, Any] = {
            "id": str(group.id),
            "name": group.name,
            "group_kind": group_kind,
        }
        if group_kind == "META":
            summary["connected_families"] = list(
                MetaFamilyMembership.objects.filter(meta_family=group)
                .select_related("family")
                .order_by("family__name")
                .values("family_id", "family__name")
            )
        return summary

    def _serialize_group_plan_option_summary(
        self,
        option: GroupPlanOption,
        *,
        response: str | None = None,
        note: str | None = None,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "plan_option_id": str(option.id),
            "label": option.label,
            "title": option.title,
            "start_time": option.start_time.isoformat(),
            "end_time": option.end_time.isoformat(),
        }
        if response is not None:
            payload["response"] = response
        if note is not None:
            payload["note"] = note
        return payload

    def _resolve_group_plan_title_match(
        self,
        *,
        queryset: models.QuerySet[GroupPlan],
        plan_title: str,
    ) -> GroupPlan | None:
        exact_matches = list(queryset.filter(title__iexact=plan_title)[:2])
        if len(exact_matches) == 1:
            return exact_matches[0]
        if len(exact_matches) > 1:
            raise ValueError(
                "Multiple open group plans matched that exact title. Use plan_id instead."
            )

        contains_matches = list(queryset.filter(title__icontains=plan_title)[:2])
        if len(contains_matches) == 1:
            return contains_matches[0]
        if len(contains_matches) > 1:
            raise ValueError(
                "Multiple open group plans matched that title. Use plan_id instead."
            )
        return None

    def _resolve_network_group_plan(
        self,
        *,
        user: User,
        family: FamilyGroup,
        plan_id: Any = None,
        plan_title: Any = None,
        context_payload: dict[str, Any] | None = None,
    ) -> GroupPlan:
        normalized_plan_id = self._normalize_text(plan_id) or self._normalize_text(
            (context_payload or {}).get("plan_id")
        )
        normalized_plan_title = self._normalize_text(plan_title)
        normalized_group_id = self._normalize_text(
            (context_payload or {}).get("group_id")
        )

        queryset = GroupPlan.objects.select_related("family_group").prefetch_related(
            "plan_options"
        )
        if normalized_group_id:
            active_group = self._get_accessible_group(user, normalized_group_id)
            if active_group is None:
                raise ValueError("Active group is not accessible for this user.")
            queryset = queryset.filter(family_group=active_group)

        plan: GroupPlan | None = None
        if normalized_plan_id:
            plan = queryset.filter(id=normalized_plan_id).first()
            if plan is None:
                raise ValueError("Open group plan was not found.")
        else:
            open_queryset = queryset.filter(status="OPEN")
            if normalized_plan_title:
                plan = self._resolve_group_plan_title_match(
                    queryset=open_queryset,
                    plan_title=normalized_plan_title,
                )
                if plan is None:
                    raise ValueError("Open group plan title was not found.")
            else:
                raise ValueError("plan_id or plan_title is required.")

        if plan is None:
            raise ValueError("Open group plan was not found.")
        if plan.status != "OPEN":
            raise ValueError("Responses can only be submitted for open group plans.")
        if self._get_group_kind(plan.family_group) != "META":
            raise ValueError(
                "Family agent can only set date responses for network group plans."
            )
        if not MetaFamilyMembership.objects.filter(
            family=family,
            meta_family=plan.family_group,
        ).exists():
            raise ValueError(
                "Current family does not have access to that network plan."
            )

        has_permission, error_msg = validate_family_admin_permission(
            user,
            family,
            "respond to network plan",
        )
        if not user.is_staff and not has_permission:
            raise ValueError(
                error_msg
                or "Current user does not have permission to respond for this family."
            )

        return plan

    def _resolve_group_plan_option_response_target(
        self,
        *,
        plan: GroupPlan,
        item: dict[str, Any],
    ) -> GroupPlanOption:
        prefetched_options = list(plan.plan_options.all())
        normalized_option_id = self._normalize_text(item.get("plan_option_id"))
        if normalized_option_id:
            for option in prefetched_options:
                if str(option.id) == normalized_option_id:
                    return option
            raise ValueError(
                "plan_option_id did not match an option on that group plan."
            )

        candidates = prefetched_options
        resolved_start_time = self._parse_group_plan_option_datetime(
            item.get("start_time"),
            field_name="start_time",
        )
        if resolved_start_time is not None:
            candidates = [
                option
                for option in candidates
                if option.start_time == resolved_start_time
            ]

        resolved_date = self._parse_selected_date(item.get("date"))
        if resolved_date is not None:
            candidates = [
                option
                for option in candidates
                if option.start_time.astimezone(NETWORK_PLAN_TIMEZONE).date()
                == resolved_date
            ]

        normalized_option_label = self._normalize_text(item.get("option_label")).lower()
        if normalized_option_label:
            exact_matches = [
                option
                for option in candidates
                if normalized_option_label
                in {
                    self._normalize_text(option.label).lower(),
                    self._normalize_text(option.title).lower(),
                }
            ]
            if len(exact_matches) == 1:
                candidates = exact_matches
            elif len(exact_matches) > 1:
                candidates = exact_matches
            else:
                contains_matches = [
                    option
                    for option in candidates
                    if normalized_option_label
                    in (
                        f"{self._normalize_text(option.label)} "
                        f"{self._normalize_text(option.title)}"
                    ).lower()
                ]
                if contains_matches:
                    candidates = contains_matches

        if len(candidates) == 1:
            return candidates[0]

        if not candidates:
            raise ValueError("No group plan option matched that date selection.")

        matching_options = [
            self._serialize_group_plan_option_summary(option)
            for option in candidates[:3]
        ]
        raise ValueError(
            "Multiple group plan options matched that date selection. "
            f"Use plan_option_id or start_time to disambiguate. Matches: {matching_options}"
        )

    def _parse_event_datetime(self, value: Any, *, field_name: str) -> datetime:
        if isinstance(value, datetime):
            parsed = value
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=datetime_timezone.utc)
            return parsed

        normalized = self._normalize_text(value)
        if not normalized:
            raise ValueError(f"{field_name} is required.")

        parsed_maybe = parse_datetime(normalized)
        if parsed_maybe is None:
            raise ValueError(f"{field_name} must be a valid ISO-8601 datetime.")

        parsed = parsed_maybe
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime_timezone.utc)
        return parsed

    def _normalize_scope(self, scope: Any) -> str:
        normalized_scope = self._normalize_text(scope).lower()
        if not normalized_scope:
            raise ValueError("scope is required.")

        if normalized_scope not in {"immediate_family", "network_public"}:
            raise ValueError("scope must be 'immediate_family' or 'network_public'.")

        return normalized_scope

    def _get_immediate_family_ids(self, user: User) -> set[str]:
        user_family_ids = list(
            user.family_memberships.filter(is_active=True).values_list(
                "family_id", flat=True
            )
        )
        if not user_family_ids:
            return set()

        family_types = dict(
            FamilyGroupType.objects.filter(family_id__in=user_family_ids).values_list(
                "family_id", "type"
            )
        )
        return {
            str(family_id)
            for family_id in user_family_ids
            if family_types.get(family_id) != "META"
        }

    def _query_accessible_events(self, user: User) -> models.QuerySet[Event]:
        from core.mixins import EventAccessMixin

        class _FamilyAgentEventAccess(EventAccessMixin):
            pass

        return _FamilyAgentEventAccess().get_accessible_events(user)

    def _resolve_network_family_ids(
        self, *, user: User, group_id: str | None
    ) -> set[str]:
        if not group_id:
            raise ValueError("group_id is required for network_public scope.")

        network_group = self._get_accessible_group(user, group_id)
        if network_group is None:
            raise ValueError("Active network group is not accessible for this user.")

        if self._get_group_kind(network_group) != "META":
            raise ValueError("network_public scope requires a META group.")

        connected_family_ids = {
            str(family_id)
            for family_id in MetaFamilyMembership.objects.filter(
                meta_family=network_group
            ).values_list("family_id", flat=True)
        }
        return connected_family_ids

    def _get_all_connected_network_family_ids(self, user: User) -> set[str]:
        immediate_family_ids = self._get_immediate_family_ids(user)
        if not immediate_family_ids:
            return set()

        meta_family_ids = set(
            MetaFamilyMembership.objects.filter(
                family_id__in=immediate_family_ids
            ).values_list("meta_family_id", flat=True)
        )
        if not meta_family_ids:
            return set()

        return {
            str(family_id)
            for family_id in MetaFamilyMembership.objects.filter(
                meta_family_id__in=meta_family_ids
            ).values_list("family_id", flat=True)
        }

    def _normalize_member_filter_value(self, value: Any) -> tuple[list[int], list[str]]:
        if isinstance(value, str):
            normalized_value = self._normalize_text(value)
            if not normalized_value:
                return [], []

            if normalized_value.startswith("user:"):
                try:
                    return [int(normalized_value[5:].strip())], []
                except ValueError:
                    return [], []

            if normalized_value.startswith("child:"):
                child_id = normalized_value[6:].strip()
                return [], [child_id] if child_id else []

        return [], []

    def _normalize_member_filters(
        self, member_filters: Any
    ) -> tuple[bool, list[int], list[str]]:
        if member_filters is None:
            return False, [], []

        user_ids: list[int] = []
        child_ids: list[str] = []

        if isinstance(member_filters, str):
            tokens = [
                token
                for token in member_filters.split(",")
                if self._normalize_text(token)
            ]
        elif isinstance(member_filters, (list, tuple, set)):
            tokens = [
                token
                for token in [
                    self._normalize_text(raw_token) for raw_token in member_filters
                ]
                if token
            ]
        else:
            tokens = [
                token for token in [self._normalize_text(member_filters)] if token
            ]

        for token in tokens:
            normalized_user_ids, normalized_child_ids = (
                self._normalize_member_filter_value(token)
            )
            user_ids.extend(normalized_user_ids)
            child_ids.extend(normalized_child_ids)

        return (
            bool(user_ids or child_ids),
            sorted(set(user_ids)),
            sorted({cid for cid in child_ids if self._normalize_text(cid)}),
        )

    def _serialize_family_group_payload(
        self, family_group: FamilyGroup | None
    ) -> dict[str, Any] | None:
        if family_group is None:
            return None
        return {
            "id": str(family_group.id),
            "name": family_group.name,
            "group_kind": self._get_group_kind(family_group),
        }

    def _is_household_block(self, event: Event) -> bool:
        if event.internal_calendar_id is None:
            return True

        internal_calendar = getattr(event, "internal_calendar", None)
        if internal_calendar is None:
            return True

        if internal_calendar.associated_users.exists():
            return False
        if internal_calendar.associated_children.exists():
            return False

        return True

    def _resolve_event_ownership_labels(
        self, event: Event
    ) -> tuple[str | None, str | None]:
        from users.event_ownership import resolve_event_ownership

        ownership = resolve_event_ownership(event)
        associated_user = None
        if ownership["display_member"] is not None:
            if ownership["ownership_source"] in {
                "associated_user",
                "associated_child",
                "calendar_owner",
            }:
                associated_user = ownership["display_member"]["name"]

        calendar_owner = None
        display_member = ownership["display_member"]
        if (
            ownership["ownership_source"] == "calendar_owner"
            and display_member is not None
        ):
            calendar_owner = display_member["name"]

        if calendar_owner is None and event.creator_id:
            calendar_owner = event.creator.get_full_name() or event.creator.username

        return associated_user, calendar_owner

    def _serialize_block(
        self, *, event: Event, is_immediate_family: bool
    ) -> dict[str, Any]:
        associated_user, calendar_owner = self._resolve_event_ownership_labels(event)
        return {
            "event_id": str(event.id),
            "start_time": event.start_time.isoformat(),
            "end_time": event.end_time.isoformat(),
            "title": event.title,
            "associated_user": associated_user,
            "calendar_owner": calendar_owner,
            "family_group": self._serialize_family_group_payload(event.family_group),
            "visibility": event.visibility,
            "is_household_block": self._is_household_block(event),
            "is_immediate_family": is_immediate_family,
        }

    def _parse_selected_date(self, value: Any) -> date | None:
        if isinstance(value, datetime):
            return value.astimezone(NETWORK_PLAN_TIMEZONE).date()
        if isinstance(value, date):
            return value

        normalized_value = self._normalize_text(value)
        if not normalized_value:
            return None

        candidate_values = [normalized_value]
        if len(normalized_value) >= 10:
            candidate_values.append(normalized_value[:10])

        for candidate in candidate_values:
            try:
                return date.fromisoformat(candidate)
            except ValueError:
                continue

        parsed_datetime = parse_datetime(normalized_value)
        if parsed_datetime is None:
            return None
        if parsed_datetime.tzinfo is None:
            parsed_datetime = parsed_datetime.replace(tzinfo=NETWORK_PLAN_TIMEZONE)
        return parsed_datetime.astimezone(NETWORK_PLAN_TIMEZONE).date()

    def _tokenize_search_query(self, query: str) -> list[str]:
        return [
            token
            for token in re.findall(r"[a-z0-9]+", query.lower())
            if len(token) >= 2
        ]

    def _score_calendar_event_candidate(
        self,
        *,
        event: Event,
        normalized_query: str,
        query_tokens: list[str],
        selected_date: date | None,
        immediate_family_ids: set[str],
    ) -> int:
        title_text = self._normalize_text(event.title).lower()
        location_text = self._normalize_text(event.location).lower()
        description_text = self._normalize_text(event.description).lower()
        searchable_text = " ".join(
            part for part in [title_text, location_text, description_text] if part
        )

        score = 0
        if normalized_query and normalized_query in title_text:
            score += 60
        elif normalized_query and normalized_query in searchable_text:
            score += 30

        for token in query_tokens:
            if token in title_text:
                score += 14
            elif token in location_text:
                score += 8
            elif token in description_text:
                score += 6

        if str(event.family_group_id) in immediate_family_ids:
            score += 5

        if selected_date is not None:
            event_date = event.start_time.astimezone(NETWORK_PLAN_TIMEZONE).date()
            day_distance = abs((event_date - selected_date).days)
            if day_distance == 0:
                score += 40
            elif day_distance <= 7:
                score += max(0, 20 - day_distance * 2)

        if event.end_time >= timezone.now():
            score += 2

        return score

    def search_calendar_events(
        self,
        *,
        family: FamilyGroup,
        user: User,
        query: Any,
        selected_date: Any = None,
        window_days: Any = 21,
        limit: Any = 5,
        context_payload: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        normalized_query = self._normalize_text(query).lower()
        if not normalized_query:
            return []

        resolved_selected_date = self._parse_selected_date(
            selected_date or (context_payload or {}).get("selected_date")
        )
        try:
            normalized_window_days = int(window_days or 21)
        except (TypeError, ValueError):
            normalized_window_days = 21
        normalized_window_days = max(0, min(normalized_window_days, 90))

        try:
            normalized_limit = int(limit or 5)
        except (TypeError, ValueError):
            normalized_limit = 5
        normalized_limit = max(1, min(normalized_limit, 10))

        query_tokens = self._tokenize_search_query(normalized_query)
        fields = ("title", "location", "description")
        search_filter = Q()
        for field_name in fields:
            search_filter |= Q(**{f"{field_name}__icontains": normalized_query})
        for token in query_tokens:
            for field_name in fields:
                search_filter |= Q(**{f"{field_name}__icontains": token})

        queryset = self._query_accessible_events(user).filter(search_filter).distinct()
        if resolved_selected_date is not None:
            start_boundary = datetime.combine(
                resolved_selected_date - timedelta(days=normalized_window_days),
                time.min,
                tzinfo=NETWORK_PLAN_TIMEZONE,
            ).astimezone(datetime_timezone.utc)
            end_boundary = datetime.combine(
                resolved_selected_date + timedelta(days=normalized_window_days + 1),
                time.min,
                tzinfo=NETWORK_PLAN_TIMEZONE,
            ).astimezone(datetime_timezone.utc)
            queryset = queryset.filter(
                start_time__gte=start_boundary,
                start_time__lt=end_boundary,
            )
        else:
            queryset = queryset.filter(end_time__gte=timezone.now() - timedelta(days=7))

        candidates = list(
            queryset.select_related(
                "family_group", "creator", "internal_calendar"
            ).order_by("start_time")[:50]
        )
        immediate_family_ids = self._get_immediate_family_ids(user)

        ranked_candidates = sorted(
            [
                (
                    self._score_calendar_event_candidate(
                        event=event,
                        normalized_query=normalized_query,
                        query_tokens=query_tokens,
                        selected_date=resolved_selected_date,
                        immediate_family_ids=immediate_family_ids,
                    ),
                    event.start_time,
                    event,
                )
                for event in candidates
            ],
            key=lambda item: (-item[0], item[1]),
        )

        results: list[dict[str, Any]] = []
        for score, _, event in ranked_candidates:
            if score <= 0:
                continue
            results.append(
                {
                    "event_id": str(event.id),
                    "title": event.title,
                    "start_time": event.start_time.isoformat(),
                    "end_time": event.end_time.isoformat(),
                    "location": event.location,
                    "latitude": event.latitude,
                    "longitude": event.longitude,
                    "is_immediate_family": str(event.family_group_id)
                    in immediate_family_ids,
                }
            )
            if len(results) >= normalized_limit:
                break

        return results

    def _read_immediate_family_roster(
        self, family: FamilyGroup
    ) -> list[dict[str, Any]]:
        membership_rows = (
            FamilyMembership.objects.filter(family=family, is_active=True)
            .select_related("user")
            .order_by("user__first_name", "user__last_name", "user__username")
        )
        roster: list[dict[str, Any]] = []
        for membership in membership_rows:
            user = membership.user
            full_name = user.get_full_name()
            roster.append(
                {
                    "kind": "user",
                    "id": str(user.id),
                    "name": full_name or user.username,
                }
            )

        for child in family.children.order_by("first_name", "last_name"):
            roster.append(
                {
                    "kind": "child",
                    "id": str(child.id),
                    "name": child.get_full_name(),
                }
            )

        return roster

    def _query_blocks_for_scope(
        self,
        *,
        family: FamilyGroup,
        user: User,
        start_time: datetime,
        end_time: datetime,
        scope: str,
        group_id: str | None,
        member_filters: Any,
        include_household_blocks: bool,
    ) -> models.QuerySet[Event]:
        if scope == "immediate_family":
            queryset = self._query_accessible_events(user).filter(
                family_group=family,
                start_time__lt=end_time,
                end_time__gt=start_time,
            )

            has_filters, selected_user_ids, selected_child_ids = (
                self._normalize_member_filters(member_filters)
            )
            if has_filters:
                member_match = Q()
                if selected_user_ids:
                    member_match |= Q(
                        internal_calendar__associated_users__id__in=selected_user_ids
                    )
                if selected_child_ids:
                    member_match |= Q(
                        internal_calendar__associated_children__id__in=selected_child_ids
                    )

                if include_household_blocks:
                    queryset = queryset.filter(
                        member_match
                        | Q(internal_calendar__isnull=True)
                        | Q(
                            internal_calendar__associated_users__isnull=True,
                            internal_calendar__associated_children__isnull=True,
                        )
                    )
                else:
                    queryset = queryset.filter(member_match)
            elif not include_household_blocks:
                queryset = queryset.exclude(
                    Q(internal_calendar__isnull=True)
                    | Q(
                        internal_calendar__associated_users__isnull=True,
                        internal_calendar__associated_children__isnull=True,
                    )
                )

            return queryset.distinct().order_by("start_time")

        connected_family_ids = self._resolve_network_family_ids(
            user=user,
            group_id=group_id,
        )
        if not connected_family_ids:
            return Event.objects.none()

        queryset = Event.objects.filter(
            family_group_id__in=connected_family_ids,
            visibility="PUBLIC",
            start_time__lt=end_time,
            end_time__gt=start_time,
        )

        if not include_household_blocks:
            queryset = queryset.exclude(
                Q(internal_calendar__isnull=True)
                | Q(
                    internal_calendar__associated_users__isnull=True,
                    internal_calendar__associated_children__isnull=True,
                )
            )

        return queryset.distinct().order_by("start_time")

    def set_group_plan_date_responses(
        self,
        *,
        user: User,
        family: FamilyGroup,
        plan_id: Any = None,
        plan_title: Any = None,
        responses: Any,
        context_payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if not isinstance(responses, list) or not responses:
            raise ValueError("responses must contain at least one date response.")

        plan = self._resolve_network_group_plan(
            user=user,
            family=family,
            plan_id=plan_id,
            plan_title=plan_title,
            context_payload=context_payload,
        )

        updated_responses: list[dict[str, Any]] = []
        with transaction.atomic():
            for raw_item in responses:
                if not isinstance(raw_item, dict):
                    raise ValueError("Each response entry must be an object.")

                option = self._resolve_group_plan_option_response_target(
                    plan=plan,
                    item=raw_item,
                )
                normalized_note = self._normalize_text(raw_item.get("note"))
                if raw_item.get("clear"):
                    GroupPlanOptionResponse.objects.filter(
                        plan=plan,
                        plan_option=option,
                        family_group=family,
                        party_unit__isnull=True,
                    ).delete()
                    updated_responses.append(
                        {
                            **self._serialize_group_plan_option_summary(option),
                            "cleared": True,
                        }
                    )
                    continue

                normalized_response = self._normalize_text(
                    raw_item.get("response")
                ).upper()
                response_row, _ = GroupPlanOptionResponse.objects.update_or_create(
                    plan=plan,
                    plan_option=option,
                    family_group=family,
                    party_unit=None,
                    defaults={
                        "response": normalized_response,
                        "note": normalized_note,
                        "responded_by": user,
                        "responded_at": timezone.now(),
                    },
                )
                updated_responses.append(
                    self._serialize_group_plan_option_summary(
                        option,
                        response=response_row.response,
                        note=response_row.note,
                    )
                )

        current_responses = list(
            GroupPlanOptionResponse.objects.filter(
                plan=plan,
                family_group=family,
                party_unit__isnull=True,
            )
            .select_related("plan_option")
            .order_by("plan_option__start_time", "plan_option__created_at")
        )

        return {
            "plan_id": str(plan.id),
            "plan_title": plan.title,
            "group_id": str(plan.family_group_id),
            "group_name": plan.family_group.name,
            "response_unit_id": str(family.id),
            "response_unit_label": family.name,
            "updated_responses": updated_responses,
            "current_family_responses": [
                self._serialize_group_plan_option_summary(
                    response_row.plan_option,
                    response=response_row.response,
                    note=response_row.note,
                )
                for response_row in current_responses
            ],
        }

    def query_calendar_blocks(
        self,
        *,
        family: FamilyGroup,
        user: User,
        start_time: Any,
        end_time: Any,
        scope: str,
        group_id: str | None = None,
        member_filters: Any = None,
        include_household_blocks: bool = True,
    ) -> list[dict[str, Any]]:
        normalized_scope = self._normalize_scope(scope)
        start_datetime = self._parse_event_datetime(start_time, field_name="start_time")
        end_datetime = self._parse_event_datetime(end_time, field_name="end_time")
        if end_datetime <= start_datetime:
            raise ValueError("end_time must be after start_time.")

        blocks = self._query_blocks_for_scope(
            family=family,
            user=user,
            start_time=start_datetime,
            end_time=end_datetime,
            scope=normalized_scope,
            group_id=group_id,
            member_filters=member_filters,
            include_household_blocks=include_household_blocks,
        )

        immediate_family_ids = self._get_immediate_family_ids(user)
        return [
            self._serialize_block(
                event=event,
                is_immediate_family=str(event.family_group_id) in immediate_family_ids,
            )
            for event in blocks
        ]

    def check_time_blocked(
        self,
        *,
        family: FamilyGroup,
        user: User,
        start_time: Any,
        end_time: Any,
        scope: str,
        group_id: str | None = None,
        member_filters: Any = None,
        include_household_blocks: bool = True,
    ) -> dict[str, Any]:
        conflicts = self.query_calendar_blocks(
            family=family,
            user=user,
            start_time=start_time,
            end_time=end_time,
            scope=scope,
            group_id=group_id,
            member_filters=member_filters,
            include_household_blocks=include_household_blocks,
        )
        return {
            "blocked": bool(conflicts),
            "conflict_count": len(conflicts),
            "conflicts": conflicts,
        }

    def get_event_details(
        self,
        *,
        family: FamilyGroup,
        user: User,
        event_ids: Any,
    ) -> list[dict[str, Any]]:
        if event_ids is None:
            return []

        if isinstance(event_ids, (list, tuple, set)):
            normalized_ids = [self._normalize_text(event_id) for event_id in event_ids]
        elif isinstance(event_ids, (str, bytes)):
            normalized_ids = [self._normalize_text(event_ids)]
        else:
            normalized_ids = [self._normalize_text(event_ids)]

        normalized_ids = [event_id for event_id in normalized_ids if event_id]
        if not normalized_ids:
            return []

        events_by_id = {
            str(event.id): event
            for event in self._query_accessible_events(user).filter(
                id__in=normalized_ids
            )
        }
        connected_network_family_ids = self._get_all_connected_network_family_ids(user)
        if connected_network_family_ids:
            events_by_id.update(
                {
                    str(event.id): event
                    for event in Event.objects.filter(
                        id__in=normalized_ids,
                        family_group_id__in=connected_network_family_ids,
                        visibility="PUBLIC",
                    )
                }
            )

        immediate_family_ids = self._get_immediate_family_ids(user)
        details: list[dict[str, Any]] = []
        for event_id in normalized_ids:
            event = events_by_id.get(event_id)
            if event is None:
                continue

            is_immediate_family = str(event.family_group_id) in immediate_family_ids
            associated_user, calendar_owner = self._resolve_event_ownership_labels(
                event
            )
            payload: dict[str, Any] = {
                "event_id": str(event.id),
                "start_time": event.start_time.isoformat(),
                "end_time": event.end_time.isoformat(),
                "title": event.title,
                "associated_user": associated_user,
                "calendar_owner": calendar_owner,
                "family_group": self._serialize_family_group_payload(
                    event.family_group
                ),
                "visibility": event.visibility,
                "is_household_block": self._is_household_block(event),
                "is_immediate_family": is_immediate_family,
            }

            if is_immediate_family:
                payload.update(
                    {
                        "description": event.description,
                        "location": event.location,
                        "latitude": event.latitude,
                        "longitude": event.longitude,
                        "event_status": event.event_status,
                        "event_type": event.event_type,
                    }
                )
            else:
                # Address data is safe to expose for network-public events too
                # so the planner can find nearby places without needing private
                # description/status. Coords only — omit the description field.
                payload.update(
                    {
                        "location": event.location,
                        "latitude": event.latitude,
                        "longitude": event.longitude,
                    }
                )

            details.append(payload)

        return details

    def get_user_location(
        self,
        *,
        context_payload: dict[str, Any] | None = None,
        **_unused: Any,
    ) -> dict[str, Any] | None:
        """Return the user_location dict passed in from the mobile client.

        The serializer has already whitelisted + freshness-checked the payload,
        so here we just surface it. Returns ``None`` when absent.
        """
        if not isinstance(context_payload, dict):
            return None
        user_location = context_payload.get("user_location")
        if not isinstance(user_location, dict):
            return None
        return {
            "latitude": user_location.get("latitude"),
            "longitude": user_location.get("longitude"),
            "accuracy_m": user_location.get("accuracy_m"),
            "captured_at": user_location.get("captured_at"),
        }

    def _resolve_ucp_merchant_hint(
        self,
        *,
        merchant_url: Any = None,
        merchant_domain: Any = None,
        context_payload: dict[str, Any] | None = None,
        family: FamilyGroup | None = None,
    ) -> tuple[str | None, str | None]:
        normalized_merchant_url = self._normalize_text(merchant_url) or None
        normalized_merchant_domain = self._normalize_text(merchant_domain) or None
        if normalized_merchant_url or normalized_merchant_domain:
            return normalized_merchant_url, normalized_merchant_domain

        if not isinstance(context_payload, dict) or family is None:
            return None, None

        capture_id = self._normalize_text(context_payload.get("capture_id"))
        if not capture_id:
            return None, None

        capture = (
            InboxCapture.objects.filter(id=capture_id, family=family)
            .only("normalized_payload")
            .first()
        )
        if capture is None:
            return None, None

        payload = capture.normalized_payload or {}
        if not isinstance(payload, dict):
            return None, None
        return (
            self._normalize_text(payload.get("source_url")) or None,
            self._normalize_text(payload.get("source_domain")) or None,
        )

    def search_ucp_products(
        self,
        *,
        family: FamilyGroup,
        query: Any = None,
        merchant_url: Any = None,
        merchant_domain: Any = None,
        categories: Any = None,
        min_price_minor: Any = None,
        max_price_minor: Any = None,
        currency: Any = None,
        intent: Any = None,
        limit: Any = 5,
        cursor: Any = None,
        context_payload: dict[str, Any] | None = None,
        **_unused: Any,
    ) -> dict[str, Any]:
        resolved_merchant_url, resolved_merchant_domain = (
            self._resolve_ucp_merchant_hint(
                merchant_url=merchant_url,
                merchant_domain=merchant_domain,
                context_payload=context_payload,
                family=family,
            )
        )
        if not resolved_merchant_url and not resolved_merchant_domain:
            return {
                "ok": False,
                "error": (
                    "No merchant URL is available. Provide merchant_url or "
                    "merchant_domain, or open the planner from a shopping capture."
                ),
                "products": [],
            }

        normalized_categories: list[str] | None = None
        if isinstance(categories, (list, tuple)):
            normalized_categories = [
                normalized
                for category in categories
                for normalized in [self._normalize_text(category)]
                if normalized
            ]
        elif self._normalize_text(categories):
            normalized_categories = [self._normalize_text(categories)]

        def _normalize_int(value: Any) -> int | None:
            if isinstance(value, bool):
                return None
            try:
                return int(value)
            except (TypeError, ValueError):
                return None

        normalized_limit = _normalize_int(limit) or 5
        normalized_limit = max(1, min(normalized_limit, 10))

        try:
            return UCPCatalogClient().search_catalog(
                merchant_url=resolved_merchant_url,
                merchant_domain=resolved_merchant_domain,
                query=self._normalize_text(query) or None,
                categories=normalized_categories,
                min_price_minor=_normalize_int(min_price_minor),
                max_price_minor=_normalize_int(max_price_minor),
                currency=self._normalize_text(currency) or None,
                intent=self._normalize_text(intent) or None,
                limit=normalized_limit,
                cursor=self._normalize_text(cursor) or None,
            )
        except UCPClientError as exc:
            return {
                "ok": False,
                "error": str(exc),
                "products": [],
            }

    def find_nearby_restaurants(
        self,
        *,
        user: User,
        family: FamilyGroup,
        latitude: float | None = None,
        longitude: float | None = None,
        event_id: str | None = None,
        cuisine: str | None = None,
        price_level: Any = None,
        radius_m: int = 1500,
        open_now: bool = False,
        max_results: int = 5,
        **_unused: Any,
    ) -> dict[str, Any]:
        """Search nearby restaurants via the shared Google Places helper.

        Accepts either explicit ``latitude``/``longitude`` or an ``event_id``
        that the user has access to (coords + location text are pulled from the
        event). ``price_level`` can be an int or list of ints (0-4).
        """
        from events.places import search_restaurants

        resolved_lat = latitude
        resolved_lng = longitude
        near_label: str | None = None

        if event_id and (resolved_lat is None or resolved_lng is None):
            details = self.get_event_details(
                family=family, user=user, event_ids=[event_id]
            )
            if not details:
                return {
                    "ok": False,
                    "error": "Event not found or not accessible.",
                    "restaurants": [],
                }
            event_detail = details[0]
            resolved_lat = event_detail.get("latitude") or resolved_lat
            resolved_lng = event_detail.get("longitude") or resolved_lng
            near_label = event_detail.get("location") or event_detail.get("title")

        if resolved_lat is None or resolved_lng is None:
            if not near_label:
                return {
                    "ok": False,
                    "error": (
                        "No coordinates available. Provide latitude/longitude or "
                        "an accessible event_id with a geocoded location."
                    ),
                    "restaurants": [],
                }

        price_levels_list: list[int] | None = None
        if price_level is not None:
            if isinstance(price_level, (list, tuple, set)):
                price_levels_list = []
                for candidate in price_level:
                    try:
                        price_levels_list.append(int(candidate))
                    except (TypeError, ValueError):
                        continue
            else:
                try:
                    price_levels_list = [int(price_level)]
                except (TypeError, ValueError):
                    price_levels_list = None

        result = search_restaurants(
            text_query=near_label,
            near_latitude=resolved_lat if resolved_lat is not None else None,
            near_longitude=resolved_lng if resolved_lng is not None else None,
            radius_m=int(radius_m or 1500),
            cuisine=cuisine if isinstance(cuisine, str) and cuisine.strip() else None,
            price_levels=price_levels_list,
            open_now=bool(open_now),
            max_results=int(max_results or 5),
            near_label=near_label,
        )
        return {
            "ok": True,
            "restaurants": result.get("restaurants", []),
            "source": result.get("source", "empty"),
            "origin": {
                "latitude": resolved_lat,
                "longitude": resolved_lng,
                "near_label": near_label,
            },
        }

    def summarize_task_board(
        self, family: FamilyGroup, *, user: User
    ) -> dict[str, Any]:
        del user
        now = timezone.now()
        pending_tasks = FamilyTask.objects.filter(
            family=family,
            status=FamilyTask.Status.PENDING,
        ).select_related("assigned_to", "linked_event", "chore_program")

        today_count = pending_tasks.filter(
            due_at__isnull=False,
            due_at__date=timezone.localdate(now),
        ).count()
        this_week_count = pending_tasks.filter(
            due_at__isnull=False,
            due_at__gte=now,
            due_at__lte=now + timedelta(days=7),
        ).count()
        overdue_count = pending_tasks.filter(due_at__lt=now).count()

        top_tasks = list(
            pending_tasks.filter(
                Q(due_at__lt=now)
                | Q(due_at__date=timezone.localdate(now))
                | Q(due_at__gte=now, due_at__lte=now + timedelta(days=7))
            ).order_by("due_at", "created_at")[:5]
        )
        if not top_tasks:
            top_tasks = list(pending_tasks.order_by("due_at", "created_at")[:5])

        return {
            "today_count": today_count,
            "this_week_count": this_week_count,
            "overdue_count": overdue_count,
            "top_tasks": [self._serialize_task_summary(task) for task in top_tasks],
        }

    def list_family_tasks(
        self,
        family: FamilyGroup,
        *,
        user: User,
        bucket: str | None = None,
        assignee: str | None = None,
        include_completed: bool = False,
        limit: int = 20,
    ) -> dict[str, Any]:
        bounded_limit = max(1, min(int(limit or 20), 50))
        queryset = FamilyTask.objects.filter(family=family).select_related(
            "assigned_to",
            "linked_event",
            "chore_program",
        )
        queryset = self._apply_task_bucket_filter(queryset, bucket=bucket)
        queryset = self._apply_task_assignee_filter(
            queryset,
            assignee=assignee,
            user=user,
        )
        if not include_completed:
            queryset = queryset.filter(status=FamilyTask.Status.PENDING)

        total_count = queryset.count()
        tasks = list(
            queryset.order_by("status", "due_at", "created_at")[:bounded_limit]
        )
        return {
            "bucket": self._normalize_text(bucket).lower() or "all",
            "assignee": self._normalize_text(assignee).lower() or "all",
            "include_completed": bool(include_completed),
            "count": total_count,
            "tasks": [self._serialize_task_summary(task) for task in tasks],
        }

    def list_grocery_lists(
        self,
        family: FamilyGroup,
        *,
        user: User,
        trip_id: str | None = None,
        list_type: str | None = None,
        show_trip_only: bool = False,
        limit: int = 20,
    ) -> dict[str, Any]:
        bounded_limit = max(1, min(int(limit or 20), 50))
        normalized_trip_id = self._normalize_text(trip_id)
        normalized_list_type = self._normalize_text(list_type).lower() or None

        queryset = (
            GroceryList.objects.filter(family=family)
            .filter(Q(is_group=True) | Q(owner=user))
            .select_related("owner", "trip", "store")
            .annotate(
                annotated_item_count=Count("items", distinct=True),
                annotated_open_item_count=Count(
                    "items",
                    filter=Q(items__is_completed=False),
                    distinct=True,
                ),
                annotated_completed_item_count=Count(
                    "items",
                    filter=Q(items__is_completed=True),
                    distinct=True,
                ),
            )
        )
        if show_trip_only:
            queryset = queryset.filter(trip__isnull=False)
        if normalized_trip_id:
            if normalized_trip_id.lower() == "none":
                queryset = queryset.filter(trip__isnull=True)
            else:
                queryset = queryset.filter(trip_id=normalized_trip_id)
        if normalized_list_type:
            queryset = queryset.filter(list_type=normalized_list_type)

        total_count = queryset.count()
        grocery_lists = list(queryset.order_by("-updated_at", "name")[:bounded_limit])
        return {
            "trip_id": normalized_trip_id or None,
            "list_type": normalized_list_type,
            "show_trip_only": bool(show_trip_only),
            "count": total_count,
            "lists": [
                self._serialize_grocery_list_summary(grocery_list)
                for grocery_list in grocery_lists
            ],
        }

    def list_chore_programs(
        self,
        family: FamilyGroup,
        *,
        user: User,
        active_only: bool = True,
        limit: int = 20,
    ) -> dict[str, Any]:
