    @action(detail=False, methods=["post"])
    def connect_google(self, request: Request) -> Response:
        """Handle Google OAuth flow and create calendar account"""
        serializer = GoogleConnectSerializer(data=request.data)
        if not serializer.is_valid():
            record_wide_event(
                request=request,
                operation="calendar.google_connect",
                outcome="error",
                reason="invalid_payload",
            )
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

        user = cast("User", request.user)
        auth_code = serializer.validated_data["auth_code"]
        state = (serializer.validated_data.get("state") or "").strip()
        redirect_uri = (serializer.validated_data.get("redirect_uri") or "").strip()
        calendar_id = serializer.validated_data.get("calendar_id", "primary")
        account_name = serializer.validated_data["account_name"]
        legacy_fallback_enabled = (
            google_calendar_oauth_flags.is_legacy_fallback_enabled(user)
        )

        if state and redirect_uri:
            try:
                validated_state = validate_google_oauth_state(state)
            except GoogleOAuthStateError as exc:
                logger.warning(
                    "Google OAuth state validation failed for user %s: %s",
                    user.id,
                    exc,
                )
                record_wide_event(
                    request=request,
                    operation="calendar.google_connect",
                    outcome="error",
                    reason="invalid_state",
                )
                return Response(
                    {"detail": "Invalid OAuth state."},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            if validated_state["user_id"] != user.id:
                record_wide_event(
                    request=request,
                    operation="calendar.google_connect",
                    outcome="error",
                    reason="state_user_mismatch",
                )
                return Response(
                    {"detail": "OAuth state does not match the authenticated user."},
                    status=status.HTTP_400_BAD_REQUEST,
                )
            if validated_state["redirect_uri"] != redirect_uri:
                record_wide_event(
                    request=request,
                    operation="calendar.google_connect",
                    outcome="error",
                    reason="state_redirect_mismatch",
                )
                return Response(
                    {"detail": "redirect_uri does not match signed OAuth state."},
                    status=status.HTTP_400_BAD_REQUEST,
                )
        elif legacy_fallback_enabled:
            redirect_uri = (
                redirect_uri
                or _default_google_redirect_uri_for_platform("mobile")
                or _default_google_redirect_uri_for_platform("web")
            )
            if not redirect_uri:
                return Response(
                    {
                        "detail": (
                            "No default Google OAuth redirect URI is configured for "
                            "legacy fallback."
                        )
                    },
                    status=status.HTTP_400_BAD_REQUEST,
                )
        else:
            errors: dict[str, list[str]] = {}
            if not state:
                errors["state"] = ["This field is required."]
            if not redirect_uri:
                errors["redirect_uri"] = ["This field is required."]
            return Response(errors, status=status.HTTP_400_BAD_REQUEST)

        oauth_client_id = getattr(settings, "GOOGLE_CALENDAR_OAUTH_CLIENT_ID", "")
        oauth_client_secret = getattr(
            settings,
            "GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET",
            "",
        )
        if not oauth_client_id or not oauth_client_secret:
            record_wide_event(
                request=request,
                operation="calendar.google_connect",
                outcome="error",
                reason="oauth_client_not_configured",
            )
            return Response(
                {"detail": "Google calendar OAuth credentials are not configured."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            with transaction.atomic():
                # Import Google Calendar utilities
                from .google_calendar_api import exchange_auth_code_for_tokens

                # Exchange auth code for access and refresh tokens
                token_data = exchange_auth_code_for_tokens(
                    auth_code=auth_code,
                    client_id=oauth_client_id,
                    client_secret=oauth_client_secret,
                    redirect_uri=redirect_uri,
                )

                if not token_data:
                    return Response(
                        {"detail": "Failed to exchange authorization code for tokens."},
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                # Check if this calendar already exists
                existing = ExternalCalendarAccount.objects.filter(
                    user=user, provider="GOOGLE", calendar_id=calendar_id
                ).first()

                if existing:
                    return Response(
                        {"detail": "This Google Calendar is already connected."},
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                # Create the calendar account - use instance + save to properly
                # use property setters for encrypted token fields
                calendar = ExternalCalendarAccount(
                    user=user,
                    provider="GOOGLE",
                    account_name=account_name,
                    calendar_id=calendar_id,
                    token_expiry=token_data.get("expires_at"),
                    is_active=True,
                    sync_enabled=True,
                )
                calendar.access_token = token_data["access_token"]
                calendar.refresh_token = token_data.get("refresh_token")
                calendar.save()

                # Associate the user with their own calendar by default
                calendar.associated_users.add(user)

                # Create default visibility settings
                CalendarVisibility.objects.create(calendar=calendar)

                # Trigger initial sync
                try:
                    from calendars.tasks import sync_calendar as sync_calendar_task

                    transaction.on_commit(
                        lambda cid=calendar.id: sync_calendar_task.delay(cid)  # type: ignore[misc]
                    )
                    logger.info(
                        f"Initial sync task scheduled for Google calendar {calendar.id}"
                    )
                except Exception as e:
                    logger.error(
                        f"Failed to schedule initial sync for Google calendar {calendar.id}: {str(e)}"
                    )

                # Return the created calendar
                response_serializer = ExternalCalendarAccountSerializer(calendar)
                record_wide_event(
                    request=request,
                    operation="calendar.google_connect",
                    outcome="success",
                    provider="google",
                    calendar_id=calendar_id,
                )
                return Response(
                    response_serializer.data, status=status.HTTP_201_CREATED
                )

        except Exception as e:
            logger.error(f"Failed to connect Google Calendar: {str(e)}")
            record_wide_event(
                request=request,
                operation="calendar.google_connect",
                outcome="error",
                reason="unexpected_exception",
            )
            return Response(
                {"detail": "Failed to connect Google Calendar. Please try again."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

